"""Generate packages/contracts/own_voice.schema.json and own_voice.ts from the models of the own-voice API (job DP part 5). Same scheme as the other contracts (`make contracts`; a test fails if either file is
stale). Committed early: Settings > AI assistant > "Use my own voice" is built against it."""

from __future__ import annotations

import json
from typing import Any

from pydantic import BaseModel
from pydantic.json_schema import models_json_schema

from app.ownvoice import models as m
from app.packs.contracts import _ts_type

HEADER = (
    "// GENERATED by `make contracts` from services/ai-api/app/ownvoice/models.py. Do not edit.\n"
    "// The Owner's own voice, made with a recorded consent: only the Owner (second factor) makes or deletes it; no recording is ever returned; the assistant still says it is the AI assistant.\n"
)
RESPONSES: list[type[BaseModel]] = [m.SentenceOut, m.OwnVoiceOut]
REQUESTS: list[type[BaseModel]] = [m.OwnVoiceIn]


def build_schema() -> dict[str, Any]:
    _, defs = models_json_schema(
        [(model, "serialization") for model in RESPONSES] + [(model, "validation") for model in REQUESTS], ref_template="#/$defs/{model}"
    )
    return {
        "$schema": "https://json-schema.org/draft/2020-12/schema",
        "$id": "own_voice.schema.json",
        "title": "The Owner's own voice (job DP)",
        "description": "Generated from services/ai-api/app/ownvoice/models.py by `make contracts`.",
        "$defs": dict(sorted(defs.get("$defs", {}).items())),
    }


def schema_text() -> str:
    return json.dumps(build_schema(), indent=2, sort_keys=False) + "\n"


def ts_text() -> str:
    defs = build_schema()["$defs"]
    lines = [HEADER]
    for name, node in defs.items():
        ts_name = name.replace("_", "")
        if "enum" in node:
            lines.append(f"export type {ts_name} = {_ts_type(node)};\n")
            continue
        props = node.get("properties", {})
        required = set(node.get("required", []))
        body = []
        for prop, spec in props.items():
            optional = "" if prop in required else "?"
            body.append(f"  {prop}{optional}: {_ts_type(spec)};")
        lines.append(f"export interface {ts_name} {{\n" + "\n".join(body) + "\n}\n")
    return "\n".join(lines)
